def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                for er, ec, sr, sc in (
                    (run[0][0], run[0][1], -dr, -dc),
                    (run[-1][0], run[-1][1], dr, dc),
                ):
                    # Extend only from an exposed endpoint of the diagonal run.
                    exposed = True
                    for ar, ac in ((er-1, ec), (er+1, ec),
                                   (er, ec-1), (er, ec+1)):
                        if 0 <= ar < h and 0 <= ac < w and grid[ar][ac] != bg:
                            exposed = False
                            break
                    if not exposed:
                        continue

                    nr, nc = er + sr, ec + sc
                    while 0 <= nr < h and 0 <= nc < w and out[nr][nc] == bg:
                        out[nr][nc] = color
                        nr += sr
                        nc += sc
    return out
